/* Groups 15/16. Pure presentation, no persistence, runtime services, listeners or clocks. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.NutriHealthCompanionGlass=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rows=v=>Array.isArray(v)?v.filter(x=>x&&typeof x==='object'):[];
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v?v:'';
const time=v=>typeof v==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v)?v:'时间未提供';
const finite=v=>typeof v==='number'&&Number.isFinite(v)?v:'未知';
const button=(label,action,id)=>`<button type="button" class="hcg-button" data-hd="${esc(action)}"${id===undefined?'':` data-id="${esc(id)}"`}>${esc(label)}</button>`;
const card=body=>`<section class="hcg-card">${body}</section>`;
const notice=text=>`<p class="hcg-notice">${esc(text)}</p>`;
const shell=(title,sub,body)=>`<div class="hcg-view"><header class="hcg-heading"><span class="hcg-eyebrow">本机合成演示</span><h2>${esc(title)}</h2><p>${esc(sub)}</p></header>${body}</div>`;
const fields=[['appearance','望 · 自述外观或精神感受'],['voice','闻 · 自述声音或呼吸感受'],['sleep','问 · 睡眠情况'],['appetite','问 · 食欲与饮食'],['feeling','问 · 其他感受']];
function renderDaily({health={}}={}){const notes=rows(health.dailyNotes);return shell('日常自述','只整理自述，不检测、不诊断。',notice('请只录入合成资料。没有图像、语音、气味或脉象检测，不提供中医辨证、体质评分或个性化建议。')+card(`<h3>记录这一天</h3><form data-form="daily"><label>日期<input name="date" type="date" value="${esc(date(health.demoDate))}" required></label>${fields.map(([k,label])=>`<label>${label}<input name="${k}" maxlength="120" placeholder="合成示例，可留空"></label>`).join('')}<p class="hcg-muted">切诊：未采集，不提供模拟脉诊结论。空白表示未填写。</p><label class="hcg-check"><input name="confirm" type="checkbox" required>我仅录入合成资料并保存在本机</label><button class="hcg-primary" type="submit">保存日常自述</button></form>`)+card(`<div class="hcg-section-title"><h3>已保存自述</h3><span>${notes.length} 条</span></div>${notes.length?`<ol class="hcg-history">${notes.slice().reverse().map(n=>`<li><h4>${esc(date(n.date)||'日期未提供')}</h4><dl>${fields.map(([k,label])=>`<div><dt>${label}</dt><dd>${esc(n[k]||'未填写')}</dd></div>`).join('')}</dl><small>${esc(n.source||'来源未填写')} · 合成自述</small></li>`).join('')}</ol>`:notice('尚未填写；未填写不代表没有异常。')}`));}
function reminderSource(r){if(r.kind!=='medication')return r.source||'来源未填写';return r.enteredBy==='instruction'?'既有医嘱录入（合成、未验证）':r.enteredBy==='user'?'用户自录（合成、未验证）':'来源未明确；编辑时需选择';}
function reminderRepeatInfo(row,localDate,inspect){if(typeof inspect==='function')return inspect(row,localDate);return Object.hasOwn(row||{},'manualRepeat')?{valid:false,due:false,label:'重复规则组件未就绪，暂不安排打卡'}:{valid:true,due:true,label:'旧安排 · 未设置重复规则，保持原逐日显示'};}
function renderReminders({health={},editId,inspectRepeat,repeatEditor=''}={}){if(typeof inspectRepeat!=='function'||!repeatEditor)return shell('提醒组件未就绪','重复编辑与打卡未启用',notice('提醒界面与操作组件版本不匹配，请重新加载同一完整版本。旧完整 v43 不理解星期规则，不能当作同等语义回退；已有记录不会自动删除。')+button('关闭','close'));const list=rows(health.reminders),edit=list.find(r=>r.id===editId);if(editId&&!edit)return shell('本页提醒','这条记录已不存在',notice('请重新选择当前记录；不创建替代安排。'));const active=list.filter(r=>!r.withdrawn&&r.enabled!==false).length,paused=list.filter(r=>!r.withdrawn&&r.enabled===false).length,withdrawn=list.filter(r=>r.withdrawn).length;return shell('本页提醒计划','记录既有合成安排，不提供处方或后台通知。',notice('关闭页面不会提醒；打卡不证明真实服药或进餐。暂停或撤回提醒不表示停药。')+`<div class="hcg-stats"><div class="hcg-stat"><small>已启用</small><strong>${active}</strong></div><div class="hcg-stat"><small>已暂停</small><strong>${paused}</strong></div><div class="hcg-stat"><small>已撤回</small><strong>${withdrawn}</strong></div></div>`+card(`<h3>已有安排 · ${list.length} 条</h3>${list.length?`<ul class="hcg-reminders">${list.map(r=>`<li><div class="hcg-reminder-top"><span class="hcg-reminder-icon" aria-hidden="true">${({water:'◉',meal:'◷',medication:'＋'})[r.kind]||'○'}</span><div><strong>${esc(r.label||'名称未填写')}</strong><small>${esc(({water:'饮水',meal:'餐食',medication:'用药自录'})[r.kind]||'类型未知')} · ${r.withdrawn?'已撤回':r.enabled===false?'已暂停':'已启用'}</small></div><time>${esc(time(r.time))}</time></div><p class="hcg-muted">${esc(reminderSource(r))}</p><p class="hcg-repeat-summary">${esc(reminderRepeatInfo(r,health.demoDate,inspectRepeat).label)} · ${reminderRepeatInfo(r,health.demoDate,inspectRepeat).due?'本演示日安排':'本演示日不安排或需核对'}</p><div class="hcg-actions">${button(r.withdrawn?'编辑并恢复':'编辑','edit-reminder',r.id)}${r.withdrawn||!reminderRepeatInfo(r,health.demoDate,inspectRepeat).valid?'':button(r.enabled===false?'恢复启用':'暂停','toggle-reminder',r.id)+button('撤回','withdraw-reminder',r.id)}</div></li>`).join('')}</ul>`:notice('尚无已保存安排；没有默认创建提醒。')}`)+card(`<h3>${edit?'编辑合成安排':'新增合成安排'}</h3>${edit?.withdrawn?notice('保存将恢复此条目但保持暂停；需再明确点击恢复启用。历史打卡保留。'):''}<form data-form="reminder" data-edit-id="${esc(edit?.id||'')}"><div class="hcg-fields"><label>类型<select name="kind">${[['meal','吃饭'],['water','喝水'],['medication','用药自录']].map(([v,l])=>`<option value="${v}"${edit?.kind===v?' selected':''}>${l}</option>`).join('')}</select></label><label>时间<input type="time" name="time" value="${time(edit?.time)==='时间未提供'?'':esc(edit.time)}" required></label></div><label>提醒名称<input name="label" value="${esc(edit?.label||'')}" maxlength="80" required placeholder="仅合成名称；不填写真实药品与剂量"></label>${repeatEditor||notice('重复规则组件未就绪，新的重复安排不可提交。')}<label>用药安排来源（用药项必选）<select name="enteredBy"><option value="">请选择，不由系统推断</option>${[['user','用户自录（合成、未验证）'],['instruction','既有医嘱录入（合成、未验证）']].map(([v,l])=>`<option value="${v}"${edit?.kind==='medication'&&edit?.enteredBy===v?' selected':''}>${l}</option>`).join('')}</select></label><p class="hcg-muted">不推荐药品、剂量或停药，不验证医嘱来源。旧预设药物也必须重新明确来源。每条仍只有一个时间；重复仅用于固定演示日筛选，不产生后台通知。</p><label class="hcg-check"><input name="confirm" type="checkbox" required>确认只使用合成既有安排，不是系统处方</label><div class="hcg-actions"><button class="hcg-primary" type="submit">${edit?.withdrawn?'保存并恢复为暂停':edit?'保存修改':'新增提醒'}</button>${button('取消填写','cancel-reminder')}</div></form>`));}
function messageCard(m,health,model,inspectRepeat){if(m.kind==='recipes')return card(`<h3>通用食谱示例</h3><p>先核对过敏原与医嘱限制；选食谱不等于进食。</p><div class="hcg-actions">${rows(model.RECIPES).map(r=>button(r.name,'recipe',r.id)).join('')}</div>${button('全部食谱','recipes')}`);if(m.kind==='report'){const water=rows(health.water).filter(r=>r.date===health.demoDate),knownWater=water.filter(r=>typeof r.ml==='number'&&Number.isFinite(r.ml)),sameDay=rows(health.meals).filter(r=>r.date===health.demoDate),w=rows(health.metrics).filter(r=>r.metric==='weight'&&typeof r.value==='number'&&Number.isFinite(r.value)&&date(r.date)&&r.unit==='kg').slice().sort((a,b)=>a.date.localeCompare(b.date));return card(`<h3>今天的小回顾</h3><p>${esc(date(health.demoDate)||'日期未提供')} · 合成记录，非 AI 分析</p><p>本演示日已记录 ${sameDay.length} 餐。</p><p>演示饮水已知合计 ${knownWater.length?finite(knownWater.reduce((sum,r)=>sum+r.ml,0)):'未知'} ml · 有值 ${knownWater.length}/${water.length} 条。</p><p>最近体重记录 ${finite(w.at(-1)?.value)} kg${w.length?' · '+esc(w.at(-1).date):''}。变化不等于健康判断或疗效。</p><div class="hcg-actions">${button('看指标趋势','metrics')}${button('看饮食记录','records')}</div>`);}if(m.kind==='reminders'){if(typeof inspectRepeat!=='function')return card('<h3>提醒组件未就绪</h3>'+notice('未启用打卡，请重新加载同一完整版本；旧完整 v43 不理解星期规则。'));const enabled=rows(health.reminders).filter(r=>r.enabled!==false&&!r.withdrawn&&reminderRepeatInfo(r,health.demoDate,inspectRepeat).due),checks=rows(health.reminderChecks).filter(c=>c.date===health.demoDate);return card(`<h3>今日合成提醒</h3><p>${esc(date(health.demoDate)||'日期未提供')} · 仅本页提醒，关闭后不会通知。</p><ul class="hcg-reminders">${enabled.map(r=>`<li><strong>${esc(r.label)}</strong><small>${esc(time(r.time))} · ${esc(reminderSource(r))} · ${esc(reminderRepeatInfo(r,health.demoDate,inspectRepeat).label)}</small>${checks.some(c=>c.reminderId===r.id)?'<span class="hcg-pill">本演示日已打卡</span>':button('打卡','check',r.id)}</li>`).join('')}</ul>${enabled.length?'':notice('本演示日没有可打卡的合成安排；未排期或规则待核对的条目可在管理中查看。')}${notice('打卡不证明真实服药或进餐；暂停或撤回不表示停药。')}${button('管理提醒','reminders')}`);}if(m.kind==='water')return card('<h3>喝水，记一小步</h3><p>明确确认后才增加记录，聊天文字不会自动计量。限液安排遵从专业人员。</p>'+button('记录演示饮水','water'));return '';}
function renderMessages({health={},model={},inspectRepeat}={}){const messages=rows(health.messages);return `<div class="hcg-view hcg-chat"><p class="hcg-notice">本机规则演示 · 非 AI 回复。此处与问询草稿分开，运行规则不会向 AI 发送。</p><p class="hcg-day">${esc(date(health.demoDate)||'日期未提供')} · 合成账号</p>${messages.length?messages.map(m=>`<article class="hcg-message ${m.role==='user'?'hcg-user':'hcg-assistant'}"><div class="hcg-avatar" aria-hidden="true">${m.role==='user'?'我':m.role==='assistant'?'禾':'·'}</div><div class="hcg-bubble"><span class="hcg-message-role">${m.role==='user'?'合成账号输入':m.role==='assistant'?(m.source==='synthetic-fixture'?'预设合成对话':m.source==='local-rule-reply'||m.source==='local-rule-report'?'本机规则回复':'来源未确认'):'消息类型未确认'}</span><p class="hcg-message-text">${esc(m.text)}</p>${Array.isArray(m.choices)&&m.choices.length?`<div class="hcg-actions">${m.choices.map(t=>`<button type="button" class="hcg-button" data-hd="say" data-text="${esc(t)}">${esc(t)}</button>`).join('')}</div>`:''}<time>${esc(date(m.date)||'日期未提供')} ${esc(time(m.time))} · ${m.source==='synthetic-fixture'?'预设合成对话':m.role==='user'?'本机演示输入':m.source==='local-rule-reply'||m.source==='local-rule-report'?'规则回复':'来源未确认'}</time></div></article>${messageCard(m,health,model,inspectRepeat)}`).join(''):notice('暂无已保存对话。输入框中的未发送文字不是已保存记录。')}</div>`;}
function renderServiceStatus({health={},storageMode='unknown'}={}){const storage=storageMode==='persistent'?'已连接本机持久存储；已核验提交才算保存。':storageMode==='memory'?'仅当前页面内存；刷新或离开后会丢失。':'存储模式尚未核对，请以当前账号状态为准。';return shell('服务与保存状态','本机规则演示，不是在线营养服务。',card(`<div class="hcg-service-hero"><span aria-hidden="true">◇</span><div><h3>AI 服务未连接</h3><p>可保存问询草稿；本机规则演示在单独入口，非 AI 回复。</p></div></div><p>当前演示日：${esc(date(health.demoDate)||'日期未提供')}</p>`)+card(`<ul class="hcg-list">${[['大模型','未配置 · 当前为规则'],['语音交互','未配置 · 无录音'],['菜品识别','未配置 · 无上传'],['后台提醒','未配置 · 关闭页面不提醒'],['真人营养师','未连接 · 无发送'],['数字形象','静态原创形象 · 无实时驱动']].map(([k,v])=>`<li><strong>${k}</strong><span>${v}</span></li>`).join('')}</ul>`)+notice(storage)+card('<h3>问询草稿与本机规则</h3><p>问询不会发往 AI。点击保存后，只有核验保存回执才显示已保存；输入中的未保存修改不能保证刷新后恢复。</p><p>持久模式下已保存的草稿可刷新后查看；临时模式只在本页内存保留。草稿按合成账号隔离，不跨设备同步，也不是加密保险库。请勿录入真实健康资料。</p><p>本机规则演示保留原有演示对话，不自动变成问询草稿。没有核验回执时，保存结果仍待核对。</p>'+button('查看问询草稿','drafts')+button('打开本机规则演示','chat')));}
const draftStamp=value=>{try{return new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}catch(_){return '时间未提供';}};
const draftAction=(title,sub,action,id,icon='▤',disabled=false)=>`<button type="button" class="hcg-draft-action"${action?` data-hd="${esc(action)}"`:''}${id?` data-id="${esc(id)}"`:''}${disabled?' disabled aria-disabled="true"':''}><span class="hcg-draft-icon" aria-hidden="true">${icon}</span><span><strong>${esc(title)}</strong><small>${esc(sub)}</small></span><span aria-hidden="true">${disabled?'':'›'}</span></button>`;
function renderInquiryDrafts({health={},drafts=[],selectedId,view='drafts',persistent=false}={}){
 const selected=drafts.find(r=>r.id===selectedId),storage=persistent?'已保存到此浏览器的合成账号':'仅本页临时草稿；刷新或离开后丢失';
 const heading=(title,action='drafts')=>`<header class="hcg-draft-heading">${button('‹ 返回',action)}<div><h2>${title}</h2><p>本机合成账号 · 未向 AI 发送</p></div>${button('服务状态','settings')}</header>`;
 const note=`<p class="hcg-draft-privacy">仅合成资料 · 不跨设备同步 · 非加密存储<br>${persistent?'成功保存的草稿可在刷新后重新打开。':'临时模式：关闭或刷新不会保留草稿。'}</p>`;
 if(view==='drafts')return `<div class="hcg-view hcg-draft-view">${heading('问询草稿','home')}<p class="hcg-notice">AI 服务未连接。这里保存问询文字，不生成 AI 答复。</p><div class="hcg-draft-section"><h3>本机草稿 <span>${drafts.length} / 60</span></h3>${button('＋ 新建草稿','new-draft')}</div>${drafts.length?`<ol class="hcg-draft-list">${drafts.slice().sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(r=>`<li>${draftAction(r.title,draftStamp(r.updatedAt)+' · '+(persistent?'本机已保存':'本页临时草稿'),'view-draft',r.id)}</li>`).join('')}</ol>`:card('<div class="hcg-draft-empty"><span aria-hidden="true">▤</span><h3>留下一条问询</h3><p>当前账号还没有已保存草稿。新建后明确点击保存，才会尝试写入。</p>'+button('新建问询草稿','new-draft')+'</div>')}${note}<div class="hcg-draft-secondary">${button('本机规则演示（非 AI）','chat')}</div></div>`;
 if(!selected)return `<div class="hcg-view hcg-draft-view">${heading('草稿不在当前档案')}<p role="alert">草稿可能因账号重置或档案恢复而变化；不会自动创建替代记录。</p>${button('查看当前草稿','drafts')}${note}</div>`;
 if(view==='unsent')return `<div class="hcg-view hcg-draft-view hcg-draft-unsent">${heading('问询未发送')}<section class="hcg-card hcg-draft-failure"><span class="hcg-draft-offline" aria-hidden="true">⌁<b>×</b></span><h2>问询未发送</h2><p>AI 服务未连接，<strong>请求未发出</strong>。</p><p>${persistent?'问询已成功保存为本机草稿。':'问询仅保留为本页临时草稿，刷新或离开后丢失。'}</p><div class="hcg-draft-actions">${draftAction('查看草稿',selected.title+' · '+draftStamp(selected.updatedAt),'view-draft',selected.id)}${draftAction('重新发送','当前不可用，AI 服务尚未接入。','',null,'↻',true)}${draftAction('服务状态','核对 AI 接入与本机保存方式。','settings',null,'◇')}${draftAction('返回编辑','继续编辑这条已保存草稿。','edit-draft',selected.id,'←')}</div></section>${note}</div>`;
 const meal=rows(health.meals).find(m=>m.date===health.demoDate&&m.slot==='breakfast');
 return `<div class="hcg-view hcg-draft-view">${heading('问询草稿')}<p class="hcg-draft-date">${esc(draftStamp(selected.updatedAt))} · 合成示例</p><article class="hcg-message hcg-user"><div class="hcg-bubble hcg-draft-question"><p class="hcg-message-text">${esc(selected.text)}</p>${button('编辑','edit-draft',selected.id)}</div></article>${meal?card(`<div class="hcg-draft-meal"><span class="hcg-draft-meal-art" aria-hidden="true">◒</span><div><h3>早餐 · 合成餐食参考</h3><p>${esc(meal.name)}</p><small>${esc(date(meal.date))} ${esc(time(meal.time))}</small><p class="hcg-muted">已有记录参考；没有作为附件发送，也不构成营养分析。</p></div></div>`):''}${card(`<div class="hcg-draft-service"><span class="hcg-draft-service-icon" aria-hidden="true">◇</span><div><h3>AI 服务未连接</h3><p>未向 AI 发送，也没有获得 AI 回复。${persistent?'问询草稿已保存在此浏览器。':'草稿只在当前页面保留。'}</p></div></div>`)}${card(`<h3>▤ ${persistent?'已保存为问询草稿':'本页临时问询草稿'}</h3><p class="hcg-muted">${esc(storage)}；可以随时继续编辑。</p>${draftAction(selected.title,draftStamp(selected.updatedAt),'edit-draft',selected.id)}`)}<div class="hcg-draft-footer">${button('编辑草稿','edit-draft',selected.id)}<button type="button" class="hcg-button" disabled aria-disabled="true">重新发送 · 未连接</button></div>${draftAction('查看未发送状态','没有网络请求，不是服务端超时。','draft-unsent',selected.id,'◇')}${note}</div>`;
}
function renderInquiryEditor({draft=null}={}){return `<div class="hcg-view hcg-draft-editor"><p class="hcg-notice">仅填写合成示例；不会向 AI 发送。未保存的修改不会自动恢复。</p><form data-form="inquiry-draft" data-edit-id="${esc(draft?.id||'')}"><label>草稿标题<input name="title" maxlength="40" value="${esc(draft?.title||'')}" placeholder="可留空，按内容生成标题"></label><label>问询内容<textarea name="text" maxlength="400" rows="5" required placeholder="例如：这是合成早餐记录，稍后想询问如何搭配。">${esc(draft?.text||'')}</textarea></label><label class="hcg-check"><input type="checkbox" name="confirm" required>确认仅录入合成资料，保存到当前合成账号</label><div class="hcg-actions"><button type="submit" class="hcg-primary">保存草稿</button>${button('取消编辑','close')}</div></form></div>`;}
return Object.freeze({reminderRepeatVersion:'manual-reminder-repeat-v1',renderDaily,renderReminders,renderMessages,renderServiceStatus,renderInquiryDrafts,renderInquiryEditor});
});
